CREATE TABLE "promotion_banners" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "subtitle" TEXT, "image_url" TEXT NOT NULL, "mobile_image_url" TEXT, "alt_text" TEXT, "button_text" TEXT, "button_url" TEXT, "placement" TEXT NOT NULL DEFAULT 'HOME_HERO', "is_active" BOOLEAN NOT NULL DEFAULT true, "starts_at" TIMESTAMP(3), "ends_at" TIMESTAMP(3), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "promotion_banners_pkey" PRIMARY KEY ("id")); CREATE INDEX "promotion_banners_is_active_placement_starts_at_ends_at_idx" ON "promotion_banners"("is_active", "placement", "starts_at", "ends_at");
